-- LESARUSS.ai Media: the first podcasts (playbook lesaruss-ai-front-door, locked by Sean 2026-10-29; Sean: "You could just pull
-- podcasts based off marketing and leadership and development for now"). 23 active shows, each found on Apple Podcasts (iTunes
-- search, its collectionId, feedUrl and 600 px artwork) and its feed read from the database server on 2026-10-29; every About is
-- written from the show's own feed description. They are LESARUSS.ai's own (tag lesaruss-ai-directory-candidate), so Vegans Explore's
-- Directory and Media leave them out (ownListing in ve-region-directory.js, rank in ve-media.js). Not Vegan businesses: no How Vegan.
-- ve-podcast reads each feed for its episodes and keeps Active / On hiatus; ve-logo-keeper copies the Apple artwork into our storage.
insert into public.listings (tenant_id, name, slug, category, specialty, status, description, website, location, address_country,
  rss_url, apple_podcasts_url, logo_url, initials, color, vegan_status, communities, tags, business_status, crawl_source, details)
select '00000000-0000-4000-a000-000000000001', v.name, v.slug, 'Podcasts', v.topic, 'approved', v.about, '', 'Online', 'US',
  v.feed, v.apple, v.art, v.ini, '#C1440D', null, array['all'], array['lesaruss-ai-directory-candidate'], v.status, 'lesaruss-ai-podcasts',
  jsonb_build_object('media_type', 'podcast', 'hosts', to_jsonb(v.hosts), 'topics', jsonb_build_array(lower(v.topic)),
    'platforms', jsonb_build_object('apple', v.apple),
    'admin_notes', jsonb_build_array(jsonb_build_object('at', now(), 'by', 'Logan', 'kind', 'note',
      'text', 'LESARUSS.ai Media, ' || v.topic || ' (playbook lesaruss-ai-front-door). Found on Apple Podcasts; About from the show''s own feed.')))
from (values
  ('marketing-school-podcast', 'Marketing School', 'Marketing', 'Neil Patel and Eric Siu share daily, practical digital marketing lessons: SEO, content, social media, email and conversion, from people who run marketing every day.', 'https://feeds.megaphone.fm/ESHO5419936864', 'https://podcasts.apple.com/us/podcast/id1138869817', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/8e/07/93/8e079362-34c2-d2bd-6944-0b2ca35e470f/mza_17827701165108339903.jpeg/600x600bb.jpg', 'MS', 'OPERATIONAL', array['Neil Patel', 'Eric Siu']),
  ('social-media-marketing-podcast', 'Social Media Marketing Podcast', 'Marketing', 'Weekly since 2012: Social Media Examiner''s Michael Stelzner interviews marketing pros on new strategies and actionable tips to improve your marketing.', 'https://rss.art19.com/social-media-marketing-podcast', 'https://podcasts.apple.com/us/podcast/id549899114', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts125/v4/33/e6/12/33e61299-de62-fa96-28cf-481784a4919d/mza_5512121408288682257.jpeg/600x600bb.jpg', 'SM', 'OPERATIONAL', array['Michael Stelzner']),
  ('the-amy-porterfield-show', 'The Amy Porterfield Show', 'Marketing', 'Helping online business owners grow their revenue, audience and team sustainably, from Amy Porterfield''s 16+ years in business and conversations with leaders.', 'https://feeds.megaphone.fm/YAP3268529120', 'https://podcasts.apple.com/us/podcast/id594703545', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/9a/8a/76/9a8a76e1-c463-a35f-844c-8c4f5a6dedc1/mza_7930761518817712453.jpg/600x600bb.jpg', 'AP', 'OPERATIONAL', array['Amy Porterfield']),
  ('everyone-hates-marketers', 'Everyone Hates Marketers', 'Marketing', 'A no-fluff marketing show by Louis Grenier on customer research, strategy, positioning, product and content marketing, messaging and branding.', 'https://rss.pdrl.fm/32245f/feeds.transistor.fm/everyone-hates-marketers', 'https://podcasts.apple.com/us/podcast/id1221256195', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts221/v4/67/7d/b7/677db72c-8e09-6c2f-5a96-e9427e327dde/mza_12716113863323402538.jpg/600x600bb.jpg', 'EH', 'CLOSED_TEMPORARILY', array['Louis Grenier']),
  ('the-marketing-millennials', 'The Marketing Millennials', 'Marketing', 'Daniel Murray unpacks the playbooks of marketing leaders from companies like Gymshark and Shopify, ready to take into your weekly marketing meeting.', 'https://feeds.megaphone.fm/the-marketing-millennials', 'https://podcasts.apple.com/us/podcast/id1527434899', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/00/00/1c/00001c13-8020-dcce-9b6a-fc0a35cfa5e5/mza_7829015603691408026.jpeg/600x600bb.jpg', 'MM', 'OPERATIONAL', array['Daniel Murray']),
  ('the-duct-tape-marketing-podcast', 'The Duct Tape Marketing Podcast', 'Marketing', 'Small business marketing expert John Jantsch interviews authors, entrepreneurs and thought leaders on marketing strategies that grow your business.', 'https://rss.libsyn.com/shows/18353/destinations/12167.xml', 'https://podcasts.apple.com/us/podcast/id78797836', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts221/v4/4a/be/48/4abe48bd-10ea-f949-e8ad-8b23be7e75d1/mza_12138050969784198627.jpg/600x600bb.jpg', 'DT', 'OPERATIONAL', array['John Jantsch']),
  ('marketing-over-coffee', 'Marketing Over Coffee', 'Marketing', 'John Wall and Christopher Penn talk marketing at the intersection of marketing and technology.', 'http://feeds.feedburner.com/marketingovercoffee', 'https://podcasts.apple.com/us/podcast/id251299460', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts113/v4/09/53/d3/0953d3e2-c1fb-1741-02eb-c5ac576d2cd2/mza_7059938016176568118.jpg/600x600bb.jpg', 'MO', 'OPERATIONAL', array['John Wall', 'Christopher Penn']),
  ('the-garyvee-audio-experience', 'The GaryVee Audio Experience', 'Marketing', 'Gary Vaynerchuk''s keynotes on marketing and business, interviews and fireside chats.', 'https://anchor.fm/s/f39a864/podcast/rss', 'https://podcasts.apple.com/us/podcast/id928159684', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts221/v4/07/f3/8f/07f38f30-1dc3-005e-8d78-bbbad350b6af/mza_11630234783161659305.jpg/600x600bb.jpg', 'GA', 'OPERATIONAL', array['Gary Vaynerchuk']),
  ('hbr-ideacast', 'HBR IdeaCast', 'Leadership', 'Harvard Business Review''s weekly podcast with the leading thinkers in business and management.', 'http://feeds.harvardbusiness.org/harvardbusiness/ideacast', 'https://podcasts.apple.com/us/podcast/id152022135', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/28/4b/4e/284b4e44-9a28-dabf-e853-e60c43e380ad/mza_6581779795008535928.jpg/600x600bb.jpg', 'HI', 'OPERATIONAL', array['Harvard Business Review']),
  ('coaching-for-leaders', 'Coaching for Leaders', 'Leadership', 'Leaders are made, not born. Every Monday since 2011, Dave Stachowiak helps leaders thrive at the points where what worked yesterday stops working.', 'https://feeds.podcastmirror.com/coaching-for-leaders', 'https://podcasts.apple.com/us/podcast/id458827716', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/75/34/c8/7534c834-8968-0c0a-21a8-e61200403d4d/mza_6042234691568342112.png/600x600bb.jpg', 'CF', 'OPERATIONAL', array['Dave Stachowiak']),
  ('maxwell-leadership-podcast', 'Maxwell Leadership Podcast', 'Leadership', 'John Maxwell on becoming a transformational leader: the principles, practices and process of influencing people to make a positive difference.', 'https://rss.libsyn.com/shows/124817/destinations/741200.xml', 'https://podcasts.apple.com/us/podcast/id1416206538', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts221/v4/b8/9b/2b/b89b2b74-c7d1-d36d-36f9-e12d425d020b/mza_17409606098947616346.png/600x600bb.jpg', 'ML', 'OPERATIONAL', array['John Maxwell']),
  ('coaching-real-leaders', 'Coaching Real Leaders', 'Leadership', 'Leadership coach Muriel Wilkins takes you inside real coaching sessions with high performers working through professional challenges.', 'https://rss.art19.com/coaching-real-leaders', 'https://podcasts.apple.com/us/podcast/id1545444200', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/a5/6a/1f/a56a1f4e-4d5a-6400-3c2b-0f040e9cbebc/mza_15007013124949291010.jpeg/600x600bb.jpg', 'CR', 'OPERATIONAL', array['Muriel Wilkins']),
  ('entreleadership', 'EntreLeadership', 'Leadership', 'Dave Ramsey and coach John Felkins share strategies, leadership principles and real-world lessons for scaling and running a business.', 'https://feeds.megaphone.fm/RM6855404952', 'https://podcasts.apple.com/us/podcast/id435836905', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/e0/fa/89/e0fa8915-2834-4906-7010-b916acbd45c5/mza_13743254506826309571.jpg/600x600bb.jpg', 'E', 'OPERATIONAL', array['Dave Ramsey', 'John Felkins']),
  ('a-bit-of-optimism', 'A Bit of Optimism', 'Leadership', 'Simon Sinek explores why people do what they do, and what helps someone find joy and meaning in their work and life.', 'https://rss2.flightcast.com/mbqbwjr8ssv2vt5jgwcv3w20.xml', 'https://podcasts.apple.com/us/podcast/id1515385282', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/69/f3/0c/69f30c74-d45b-bbca-a756-11aaf092ac3e/mza_8637948344782580934.jpg/600x600bb.jpg', 'AB', 'OPERATIONAL', array['Simon Sinek']),
  ('the-look-and-sound-of-leadership', 'The Look & Sound of Leadership', 'Leadership', 'Executive coaching tips from Tom Henschel to help you be perceived at work the way you want to be perceived.', 'https://rss.buzzsprout.com/1807501.rss', 'https://podcasts.apple.com/us/podcast/id280383574', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts221/v4/6c/5a/09/6c5a0996-fcbf-81b7-f05a-4febea38ea8c/mza_2726308400565277758.jpg/600x600bb.jpg', 'LS', 'OPERATIONAL', array['Tom Henschel']),
  ('the-learning-leader-show', 'The Learning Leader Show', 'Leadership', 'Leaders are learners. Ryan Hawk talks with entrepreneurs, CEOs, athletes, coaches and authors about getting better every day.', 'https://rss.libsyn.com/shows/65162/destinations/259291.xml', 'https://podcasts.apple.com/us/podcast/id985396258', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts221/v4/fb/3c/0e/fb3c0e91-f0a8-44ef-403f-1ec20bece9e0/mza_454404552678702443.png/600x600bb.jpg', 'LL', 'OPERATIONAL', array['Ryan Hawk']),
  ('the-tim-ferriss-show', 'The Tim Ferriss Show', 'Development', 'Tim Ferriss deconstructs world-class performers from investing, sports, business and beyond to find the tools and tactics you can use.', 'https://rss.art19.com/tim-ferriss-show', 'https://podcasts.apple.com/us/podcast/id863897795', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts126/v4/18/39/b4/1839b420-7aff-c501-5d0d-af2842fba013/mza_6255154260686997849.jpeg/600x600bb.jpg', 'TF', 'OPERATIONAL', array['Tim Ferriss']),
  ('the-school-of-greatness', 'The School of Greatness', 'Development', 'Lewis Howes interviews leaders in business, sports, science and health to help you unlock your greatness and live your best life.', 'https://feeds.simplecast.com/AAvup9Zz', 'https://podcasts.apple.com/us/podcast/id596047499', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts221/v4/b2/17/b5/b217b58d-a605-8828-2cfe-3694a55a6284/mza_2870672035194873125.jpg/600x600bb.jpg', 'SO', 'OPERATIONAL', array['Lewis Howes']),
  ('the-mel-robbins-podcast', 'The Mel Robbins Podcast', 'Development', 'Mel Robbins shares simple, research-backed advice, science-based tools and personal stories to help you change your life.', 'https://feeds.simplecast.com/UCwaTX1J', 'https://podcasts.apple.com/us/podcast/id1646101002', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/ab/66/a5/ab66a5f5-b52b-c70a-227b-0721bd9dc660/mza_13546984924981879479.jpg/600x600bb.jpg', 'MR', 'OPERATIONAL', array['Mel Robbins']),
  ('the-jordan-harbinger-show', 'The Jordan Harbinger Show', 'Development', 'In-depth conversations with people at the top of their game, unpacked into practical lessons for your work, life and relationships.', 'https://rss.introcast.io:443/1344999619/www.podcastone.com/podcast?categoryID2=1237', 'https://podcasts.apple.com/us/podcast/id1344999619', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/ce/57/a9/ce57a912-523d-5e81-f461-c71591eb2b4b/mza_855972047978822038.jpeg/600x600bb.jpg', 'JH', 'OPERATIONAL', array['Jordan Harbinger']),
  ('the-diary-of-a-ceo', 'The Diary Of A CEO', 'Development', 'Steven Bartlett''s raw, human conversations with experts, thinkers and business leaders, sharing lessons for better, more fulfilling lives.', 'https://rss2.flightcast.com/xmsftuzjjykcmqwolaqn6mdn', 'https://podcasts.apple.com/us/podcast/id1291423644', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts221/v4/69/af/0d/69af0ddd-1e0f-7ae3-c84b-88f18e31ad0c/mza_14445920128472365296.png/600x600bb.jpg', 'DO', 'OPERATIONAL', array['Steven Bartlett']),
  ('how-i-built-this', 'How I Built This', 'Development', 'Guy Raz interviews well-known entrepreneurs on how they built their brands, from moments of doubt and failure to their eventual success.', 'https://feeds.megaphone.fm/VMP2035168248', 'https://podcasts.apple.com/us/podcast/id1150510297', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts221/v4/15/96/f6/1596f64d-347f-87b6-b5f2-04dcc079a598/mza_10725073278164213531.jpeg/600x600bb.jpg', 'HI', 'OPERATIONAL', array['Guy Raz']),
  ('masters-of-scale', 'Masters of Scale', 'Development', 'Founders and CEOs share the lessons and strategies that grew some of the world''s most fascinating companies, with founding host Reid Hoffman.', 'https://rss.art19.com/masters-of-scale', 'https://podcasts.apple.com/us/podcast/id1227971746', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/13/4b/81/134b8173-d713-cbb2-2d3b-4a8692bd87c0/mza_996010941061703843.jpeg/600x600bb.jpg', 'MO', 'OPERATIONAL', array['Reid Hoffman'])
) as v(slug, name, topic, about, feed, apple, art, ini, status, hosts)
where not exists (select 1 from public.listings l where l.slug = v.slug and l.status = 'approved');
